import { sql } from "drizzle-orm";
import {
  bigint,
  check,
  date,
  doublePrecision,
  index,
  pgSequence,
  pgTable,
  text,
  timestamp,
  uuid,
} from "drizzle-orm/pg-core";
import { user } from "./auth";
import { inList } from "./sql";

const TZ = { withTimezone: true } as const;

// Global change counter for sync (ADR-0002). A trigger (migration 0002) stamps
// every insert and update of a synced table with nextval and now().
export const syncRev = pgSequence("sync_rev");

// Columns every synced table carries. The id is generated by the device.
export const syncColumns = () => ({
  id: uuid("id").primaryKey(),
  userId: uuid("user_id")
    .notNull()
    .references(() => user.id, { onDelete: "cascade" }),
  rev: bigint("rev", { mode: "number" }).notNull().default(sql`nextval('sync_rev')`),
  createdAt: timestamp("created_at", TZ).defaultNow().notNull(),
  updatedAt: timestamp("updated_at", TZ).defaultNow().notNull(),
  deletedAt: timestamp("deleted_at", TZ),
});

// Unit per kind: weight kg, body_fat %, circumferences cm.
export const BODY_KINDS = ["weight", "body_fat", "waist", "chest", "arms", "legs", "neck", "hips"] as const;
export type BodyKind = (typeof BODY_KINDS)[number];

export const MEASUREMENT_SOURCES = ["manual", "health_connect", "ios_import"] as const;

// Manual weigh-ins and tape measurements, written by the client.
export const bodyMeasurement = pgTable(
  "body_measurement",
  {
    ...syncColumns(),
    measuredOn: date("measured_on").notNull(),
    kind: text("kind").notNull(),
    value: doublePrecision("value").notNull(),
    source: text("source").notNull().default("manual"),
  },
  (t) => [
    index("body_measurement_user_rev_idx").on(t.userId, t.rev),
    index("body_measurement_user_day_idx").on(t.userId, t.measuredOn),
    check("body_measurement_kind_check", sql`${t.kind} in (${sql.raw(inList(BODY_KINDS))})`),
    check("body_measurement_source_check", sql`${t.source} in (${sql.raw(inList(MEASUREMENT_SOURCES))})`),
    check("body_measurement_value_check", sql`${t.value} > 0 and ${t.value} < 1000`),
  ],
);
